  const getGroundHeight = (x, z) => { const distCenter = Math.sqrt(x * x + z * z); if (distCenter < 7.5) return 0.2; const distHome = Math.sqrt((x + 20) ** 2 + (z + 14) ** 2); if (distHome < 8.2) return 0.2; const distAcademy = Math.sqrt((x - 20) ** 2 + (z + 14) ** 2); if (distAcademy < 8.2) return 0.2; const distLab = Math.sqrt((x + 20) ** 2 + (z - 14) ** 2); if (distLab < 8.2) return 0.2; const distMuseum = Math.sqrt((x - 20) ** 2 + (z - 14) ** 2); if (distMuseum < 8.2) return 0.2; const distPortal = Math.sqrt(x * x + (z - 24) ** 2); if (distPortal < 6.0) return 0.2; if (z > 7.5 && z < 18 && Math.abs(x) < 2) { const progress = (z - 7.5) / 10.5; return 0.2 + progress * 1.5; } for (const rock of STEPPING_ROCKS) { const distRock = Math.sqrt((x - rock.x) ** 2 + (z - rock.z) ** 2); if (distRock < rock.r) return rock.y; } return 0.2; };
