  const renderDiagnosticOverlay = (snapshot) => { const { viewport } = dom(); if (!viewport) return; let overlay = document.getElementById('diagnostic_overlay'); if (!overlay) { overlay = document.createElement('div'); overlay.id = 'diagnostic_overlay'; overlay.className = 'absolute bottom-3 right-3 z-50 w-[22rem] rounded-2xl border border-cyan-500/30 bg-zinc-950/88 text-zinc-100 shadow-2xl backdrop-blur-md overflow-hidden'; overlay.innerHTML = `<div class="px-4 py-3 border-b border-white/5 flex items-center justify-between"><div><div class="text-xs uppercase tracking-[0.22em] text-cyan-300/80 font-mono">Diagnostic mode</div><div class="text-sm text-zinc-200 mt-1">3D black-screen probe</div></div><button id="diagnostic_close" class="text-zinc-500 hover:text-zinc-200">×</button></div><div id="diagnostic_body" class="p-4 text-[11px] text-zinc-300 space-y-2 max-h-56 overflow-auto whitespace-pre-wrap"></div>`; viewport.appendChild(overlay); overlay.querySelector('#diagnostic_close')?.addEventListener('click', () => overlay.remove()); } const body = overlay.querySelector('#diagnostic_body'); if (body) body.textContent = JSON.stringify(snapshot, null, 2); };
  const setThreeReadiness = (partial) => { threeReadiness = { ...threeReadiness, ...partial }; diagnosticSnapshot = { phase: threeReadiness.gateOpen ? (threeReadiness.coreReady ? 'ready' : 'waiting-assets') : 'booting', camera: threeCamera ? { x: Number(threeCamera.position.x.toFixed(2)), y: Number(threeCamera.position.y.toFixed(2)), z: Number(threeCamera.position.z.toFixed(2)) } : null, sceneObjects: threeScene ? threeScene.children.length : 0, activeZone: state.activeZoneId, readiness: threeReadiness, failures: assetLoadFailures.slice(-5).map((failure) => ({ category: failure.category, asset: failure.assetPath })) }; renderDiagnosticOverlay(diagnosticSnapshot); };
  const ensureOverlay = () => { const { viewport } = dom(); if (!viewport) return null; let overlay = document.getElementById('three_loading_overlay'); if (!overlay) { overlay = document.createElement('div'); overlay.id = 'three_loading_overlay'; overlay.className = 'absolute inset-0 z-30 flex items-center justify-center bg-zinc-950/85 backdrop-blur-sm hidden'; overlay.innerHTML = `<div class="rounded-2xl border border-cyan-500/20 bg-zinc-950/90 px-5 py-4 shadow-2xl text-zinc-100 max-w-sm w-full mx-4"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl bg-cyan-500/10 border border-cyan-500/20 flex items-center justify-center text-cyan-300 animate-pulse"><svg class="w-5 h-5 animate-spin" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M4 4v5h.582m15.356 2A8.001 8.001 0 1121.228 10H18.2M4 9h5M4 9v5"/></svg></div><div><div class="text-xs uppercase tracking-[0.25em] text-cyan-300/80 font-mono">Loading 3D scene</div><div class="text-sm text-zinc-300 mt-1" id="three_loading_overlay_text">Preparing the orbital zone...</div></div></div><div class="mt-4 h-1.5 rounded-full bg-zinc-900 overflow-hidden border border-zinc-800"><div id="three_loading_overlay_bar" class="h-full w-[20%] bg-gradient-to-r from-cyan-500 to-emerald-400 animate-pulse"></div></div></div>`; viewport.appendChild(overlay); } return overlay; };
  const setLoadingText = (message, progress = 25) => { const overlay = ensureOverlay(); if (!overlay) return; overlay.classList.remove('hidden'); const text = overlay.querySelector('#three_loading_overlay_text'); const bar = overlay.querySelector('#three_loading_overlay_bar'); if (text) text.textContent = message; if (bar) bar.style.width = `${Math.max(10, Math.min(100, progress))}%`; };
  const hideLoading = () => document.getElementById('three_loading_overlay')?.classList.add('hidden');
  const updateMobileUX = () => { const { dpad, exitControls } = dom(); if (dpad) { const isMobile = window.matchMedia('(max-width: 768px)').matches; dpad.classList.toggle('opacity-100', isMobile); dpad.classList.toggle('opacity-40', !isMobile); dpad.classList.toggle('hidden', false); state.ui.mobile.dpadVisible = true; } if (exitControls) exitControls.classList.toggle('flex-col', window.matchMedia('(max-width: 480px)').matches); };
  const scheduleResize = () => { if (resizeTimeout) clearTimeout(resizeTimeout); resizeTimeout = setTimeout(() => { resizeTimeout = null; handleResize(); }, 100); };
  const updateRadarMinimap = () => { const { radarCanvas } = dom(); if (!radarCanvas || !threePlayerMesh) return; const radarCtx = radarCanvas.getContext('2d'); if (!radarCtx) return; radarCtx.clearRect(0, 0, 96, 96); const center = 48; radarCtx.strokeStyle = 'rgba(16, 185, 129, 0.15)'; radarCtx.lineWidth = 1; radarCtx.beginPath(); radarCtx.arc(center, center, 44, 0, Math.PI * 2); radarCtx.stroke(); radarCtx.beginPath(); radarCtx.arc(center, center, 24, 0, Math.PI * 2); radarCtx.stroke(); radarCtx.strokeStyle = 'rgba(16, 185, 129, 0.08)'; radarCtx.beginPath(); radarCtx.moveTo(center, 4); radarCtx.lineTo(center, 92); radarCtx.moveTo(4, center); radarCtx.lineTo(92, center); radarCtx.stroke(); for (let i = 0; i < ZONES_3D.length; i += 1) { const zone = ZONES_3D[i]; const rx = center + (zone.x / 30) * 38; const rz = center + (zone.z / 30) * 38; const color = zone.id === 'home' ? '#f59e0b' : zone.id === 'academy' ? '#10b981' : zone.id === 'lab' ? '#3b82f6' : zone.id === 'museum' ? '#a855f7' : '#ec4899'; radarCtx.fillStyle = color; radarCtx.beginPath(); radarCtx.arc(rx, rz, 4, 0, Math.PI * 2); radarCtx.fill(); } const px = center + (threePlayerMesh.position.x / 30) * 38; const pz = center + (threePlayerMesh.position.z / 30) * 38; radarCtx.fillStyle = '#ffffff'; radarCtx.shadowBlur = 10; radarCtx.shadowColor = '#10b981'; radarCtx.beginPath(); radarCtx.arc(px, pz, 3, 0, Math.PI * 2); radarCtx.fill(); radarCtx.shadowBlur = 0; };
  const clearSceneCard = () => { document.getElementById('three_scene_zone_card')?.remove(); sceneCardState = { zoneId: null, visible: false, anchor: null }; };
  const updateSceneCard = (zoneId) => { if (!threePlayerMesh) return; const zone = state.zones.find((item) => item.id === zoneId); const { viewport, sceneOverlay } = dom(); if (!zone || !viewport || !sceneOverlay) return; const existing = document.getElementById('three_scene_zone_card'); if (existing) existing.remove(); const rect = viewport.getBoundingClientRect(); const screenX = Math.min(rect.width - 30, Math.max(30, ((threePlayerMesh.position.x / 32) * rect.width) + 18)); const screenY = Math.min(rect.height - 16, Math.max(18, ((threePlayerMesh.position.z / 32) * rect.height) + 18)); const card = document.createElement('div'); card.id = 'three_scene_zone_card'; card.className = 'three-scene-card px-4 py-3'; card.innerHTML = `<div class="flex items-start gap-3"><div class="mt-0.5 w-10 h-10 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-emerald-300 shadow-inner shadow-black/20">◆</div><div class="min-w-0"><div class="text-[10px] uppercase tracking-[0.26em] text-zinc-400 font-mono mb-1">Khu vực</div><div class="three-scene-card__title text-sm font-display font-semibold text-white leading-tight">${state.language === 'vi' ? zone.vietnameseName : zone.name}</div><div class="text-[11px] text-zinc-300 mt-1 leading-relaxed">${state.language === 'vi' ? zone.description_vi : zone.description_en}</div></div></div>`; card.style.left = `${screenX}px`; card.style.top = `${screenY}px`; sceneOverlay.appendChild(card); sceneCardState = { zoneId, visible: true, anchor: card }; ui?.renderZoneHud?.(zone); clearTimeout(hudHideTimer); hudHideTimer = setTimeout(() => ui?.clearZoneHud?.(), 6000); };
  const applyZoneTheme3D = (zoneId, instant = false) => { if (!threeScene || !zoneEnvironment) return; const theme = ZONE_THEMES[zoneId] || ZONE_THEMES.home; if (!instant) { zoneTransitionState.targetZoneId = zoneId; zoneTransitionState.currentZoneId = zoneTransitionState.currentZoneId || zoneId; zoneTransitionState.progress = 0; zoneTransitionState.focusPulse = 1; zoneTransitionState.vignettePulse = 1; zoneTransitionState.lastZoneChangeAt = Date.now(); } threeScene.background = new THREE.Color(theme.skyBottom); if (threeScene.fog) threeScene.fog.color = new THREE.Color(theme.fog); if (zoneEnvironment.skyMat?.uniforms) { zoneEnvironment.skyMat.uniforms.topColor.value = new THREE.Color(theme.skyTop); zoneEnvironment.skyMat.uniforms.bottomColor.value = new THREE.Color(theme.skyBottom); } zoneEnvironment.ambientLight.color = new THREE.Color(theme.hemi); zoneEnvironment.dirLight.color = new THREE.Color(theme.dir); zoneEnvironment.fillLight.color = new THREE.Color(theme.fill); };
  const updateZoneTerrain = (now) => { for (let index = 0; index < zoneTerrainAnimations.length; index += 1) { const item = zoneTerrainAnimations[index]; if (!item || !item.group) continue; if (item.kind === 'home' && item.mound) { item.group.position.y = Math.sin(now * 0.001 + index) * 0.12; item.mound.rotation.y += 0.0012; } else if (item.kind === 'academy' && item.scanLine) { item.scanLine.position.x = -7 + ((now * 0.0018) % 14); } else if (item.kind === 'lab' && item.pipeGlow) { item.pipeGlow.material.opacity = 0.55 + (Math.sin(now * 0.003) * 0.18); } else if (item.kind === 'museum') { item.group.position.y = Math.sin(now * 0.00045 + index) * 0.03; } else if (item.kind === 'portal') { item.ringBase.rotation.z += 0.006; } } };
  const updateAnimatedObjects = (now) => { for (let i = 0; i < animatedCogs.length; i += 1) animatedCogs[i].mesh.rotation.y += animatedCogs[i].speed; for (let i = 0; i < animatedCrafts.length; i += 1) { const craft = animatedCrafts[i]; craft.mesh.position.y = craft.baseY + Math.sin(now * craft.hoverSpeed + craft.offset) * craft.hoverRange; } for (let i = 0; i < emissiveMaterials.length; i += 1) { const material = emissiveMaterials[i]; if (material) material.emissiveIntensity = 1.25 + Math.sin(now * 0.004) * 0.55; } if (spaceParticles) { spaceParticles.rotation.y += 0.0007; spaceParticles.rotation.x += 0.0003; } };
  const updatePlayerState = () => { if (!threePlayerMesh) return; threePlayerMesh.position.y = getGroundHeight(threePlayerMesh.position.x, threePlayerMesh.position.z) + 0.45; if (threePlayerAura) { threePlayerAura.position.x = threePlayerMesh.position.x; threePlayerAura.position.z = threePlayerMesh.position.z; threePlayerAura.position.y = threePlayerMesh.position.y - 0.34; } };
  const renderFrame = () => { if (threeRenderer && threeScene && threeCamera) { if (sceneCardState.visible && sceneCardState.zoneId) updateSceneCard(sceneCardState.zoneId); if (diagnosticModeEnabled && !diagnosticSnapshot) { diagnosticSnapshot = { camera: { x: Number(threeCamera.position.x.toFixed(2)), y: Number(threeCamera.position.y.toFixed(2)), z: Number(threeCamera.position.z.toFixed(2)) }, sceneObjects: threeScene.children.length, zone: state.activeZoneId, playerVisible: !!threePlayerMesh, placeholderVisible: !!threePlayerPlaceholder, rendererSize: threeRenderer.domElement ? { w: threeRenderer.domElement.width, h: threeRenderer.domElement.height } : null, hasBackground: !!threeScene.background, failures: assetLoadFailures.map((failure) => ({ category: failure.category, asset: failure.assetPath })) }; renderDiagnosticOverlay(diagnosticSnapshot); } if (threeComposer?.render) threeComposer.render(); else threeRenderer.render(threeScene, threeCamera); } };
  const detect3DZoneCollision = () => { if (!threePlayerMesh) return null; const playerBox = new THREE.Box3().setFromObject(threePlayerMesh); let detectedZoneId = null; for (let i = 0; i < zoneBoxes.length; i += 1) { const item = zoneBoxes[i]; if (item.box.intersectsBox(playerBox)) { detectedZoneId = item.id; break; } } if (detectedZoneId && state.activeZoneId !== detectedZoneId) { state.activeZoneId = detectedZoneId; audio.playNewZoneSound(); applyZoneTheme3D(detectedZoneId); ui?.renderHeaderForZone?.(state.zones.find((zone) => zone.id === detectedZoneId) || state.zones[0]); ui?.syncQuickTeleportActiveState?.(state.zones, detectedZoneId); ui?.renderZoneDetails?.(state.zones.find((zone) => zone.id === detectedZoneId) || state.zones[0]); if (detectedZoneId === 'portal') exit3DMode(); } return detectedZoneId; };
  const update3DLoops = (now) => { if (threeControls) threeControls.update(); if (zoneTransitionState.progress < 1 && zoneTransitionState.targetZoneId) { zoneTransitionState.progress = Math.min(1, zoneTransitionState.progress + 0.03); if (zoneTransitionState.progress >= 1) zoneTransitionState.currentZoneId = zoneTransitionState.targetZoneId; } if (threeMixer) threeMixer.update(0.016); updateZoneTerrain(now); updatePlayerState(); updateAnimatedObjects(now); const currentZone = detect3DZoneCollision(); if (sceneCardState.visible && !currentZone) clearSceneCard(); updateRadarMinimap(); };
  const animate3D = (ts = 0) => { threeAnimId = requestAnimationFrame(animate3D); const now = ts || performance.now(); update3DLoops(now); renderFrame(); };
